-- Administrator account controlled by ADMIN_EMAIL / ADMIN_PASSWORD variables.
ALTER TABLE portal.users ADD COLUMN managed_by_env BOOLEAN NOT NULL DEFAULT FALSE;

-- Encrypted values generated by the portal (e.g. its listmonk API token).
CREATE TABLE portal.secrets (
    key         TEXT PRIMARY KEY,
    value       TEXT NOT NULL,
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
